<?php
/**
 * Block patterns — reusable CTA starter for editor content.
 *
 * The former About / Services / Contact starter patterns now live in
 * dedicated page templates (page-templates/about.php, services.php,
 * contact.php) — single source of truth, filter-overridable. This file
 * keeps the reusable CTA pattern for any post or page.
 *
 * The CTA pattern renders through two channels:
 *   - Primary:   when the Kabel Blocks emitter is loaded, the markup is
 *                generated by the kbl3_* twin functions (byte-exact with
 *                the block save() output — no validation warnings).
 *   - Fallback:  a plain core-block version (group / heading / paragraph /
 *                buttons), so the pattern stays insertable and on-design
 *                even without the plugin (or in safe mode).
 *
 * Design system: near-black #0B0B0D band, white heading, bronze #B39A74
 * square button with black text (hover #D3BC97) — see theme.json palette.
 *
 * @package Kabel
 */

defined( 'ABSPATH' ) || exit;

/**
 * Register theme block patterns.
 */
function kabel_register_patterns(): void {
        if ( ! function_exists( 'register_block_pattern' ) ) {
                return;
        }

        register_block_pattern( 'kabel/cta-quote', array(
                'title'      => __( 'Call to action — Consult Now', 'kabel' ),
                'categories' => array( 'kabel' ),
                'content'    => kabel_cta_quote_content(),
        ) );
}
add_action( 'init', 'kabel_register_patterns' );

/**
 * The kabel/cta-quote pattern markup — channel picker.
 *
 * @return string Block markup.
 */
function kabel_cta_quote_content(): string {
        if ( function_exists( 'kbl3_section' ) ) {
                return kabel_cta_quote_content_kbl();
        }
        return kabel_cta_quote_content_core();
}

/**
 * Primary channel — kbl/* blocks via the Kabel Blocks emitter twins.
 *
 * Composed with kbl3_section / kbl3_heading / kbl3_text / kbl3_button_group
 * / kbl3_button (kabel-blocks/inc/emitter.php), so the markup is byte-exact
 * with the block save() functions and the editor opens it without
 * validation warnings. Inner blocks are joined with "\n\n" per the emitter
 * contract.
 *
 * Note: kbl/section exposes a single padTop/padBottom value (no responsive
 * variant in its attribute vocabulary), so the 120px rhythm applies at every
 * width — matching how every seeded kbl/section band behaves.
 *
 * @return string Block markup.
 */
function kabel_cta_quote_content_kbl(): string {
        $inner = kbl3_heading( array(
                'level'    => 2,
                'align'    => 'center',
                'color'    => '#FFFFFF',
                'fontSize' => 42,
                'text'     => esc_html__( 'Ready to transform your next space?', 'kabel' ),
        ) )
        . "\n\n" . kbl3_text( array(
                'align'        => 'center',
                'color'        => 'rgba(255,255,255,0.72)',
                'fontSize'     => 17,
                'contentWidth' => 620,
                'blockAlign'   => 'center',
                'text'         => esc_html__( 'Tell us your market, volume and target price — our engineers reply within one business day.', 'kabel' ),
        ) )
        . "\n\n" . kbl3_button_group( array(
                'align' => 'center',
        ), kbl3_button( array(
                'text' => esc_html__( 'Consult Now', 'kabel' ),
                'url'  => '/contact/',
        ) ) );

        return kbl3_section( array(
                'bgColor'    => '#0B0B0D',
                'padTop'     => 120,
                'padBottom'  => 120,
        ), $inner );
}

/**
 * Fallback channel — plain core blocks, same design language.
 *
 * Used when the Kabel Blocks emitter is not loaded (plugin inactive and the
 * theme's safe-mode fallback absent). Bronze square button comes from the
 * theme's core/button style defaults (radius 0) plus explicit colors. The
 * style attributes end with a trailing semicolon and follow the
 * Gutenberg save() serialization order, so inserted patterns round-trip
 * without block validation warnings.
 *
 * @return string Block markup.
 */
function kabel_cta_quote_content_core(): string {
        $heading = esc_html__( 'Ready to transform your next space?', 'kabel' );
        $sub     = esc_html__( 'Tell us your market, volume and target price — our engineers reply within one business day.', 'kabel' );
        $label   = esc_html__( 'Consult Now', 'kabel' );

        return '<!-- wp:group {"align":"wide","style":{"color":{"background":"#0B0B0D","text":"#FFFFFF"},"spacing":{"padding":{"top":"120px","bottom":"120px","left":"var:preset|spacing|40","right":"var:preset|spacing|40"}}},"layout":{"type":"constrained","contentSize":"620px"}} -->
<div class="wp-block-group alignwide has-text-color has-background" style="background-color:#0B0B0D;color:#FFFFFF;padding-top:120px;padding-right:var(--wp--preset--spacing--40);padding-bottom:120px;padding-left:var(--wp--preset--spacing--40);"><!-- wp:heading {"textAlign":"center","style":{"typography":{"fontSize":"42px"}}} -->
<h2 class="wp-block-heading has-text-align-center" style="font-size:42px;">' . $heading . '</h2>
<!-- /wp:heading -->

<!-- wp:paragraph {"align":"center","style":{"color":{"text":"rgba(255,255,255,0.72)"},"typography":{"fontSize":"17px"}}} -->
<p class="has-text-align-center has-text-color" style="color:rgba(255,255,255,0.72);font-size:17px;">' . $sub . '</p>
<!-- /wp:paragraph -->

<!-- wp:buttons {"layout":{"type":"flex","justifyContent":"center"}} -->
<div class="wp-block-buttons"><!-- wp:button {"style":{"color":{"background":"#B39A74","text":"#0B0B0D"}}} -->
<div class="wp-block-button"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="/contact/" style="background-color:#B39A74;color:#0B0B0D;">' . $label . '</a></div>
<!-- /wp:button --></div>
<!-- /wp:buttons --></div>
<!-- /wp:group -->';
}
